create table public.dd_autobuild_candidates (id uuid not null default gen_random_uuid() primary key, candidate_key text not null unique, source_type text not null, source_record_id text not null, domain text not null, title text not null, proposed_build text not null, evidence jsonb not null default '{}'::jsonb, acceptance_criteria text not null, risk_tier text not null, permission_class text not null, status text not null default 'CANDIDATE', blocker text, code_repair_work_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), lease_token uuid, lease_owner text, leased_at timestamptz, lease_expires_at timestamptz, attempt_count integer not null default 0, executor_state text not null default 'PENDING', branch_name text, pull_request_number integer, pull_request_url text, head_sha text, proof jsonb not null default '{}'::jsonb, last_error text, built_at timestamptz, proven_at timestamptz);
create table public.dd_code_repair_policy (id uuid not null default gen_random_uuid() primary key, policy_key text not null unique, detection_authority text not null, repair_executor text, branch_policy text not null, required_gates jsonb not null default '[]', auto_merge_allowed boolean not null default false, production_direct_write_allowed boolean not null default false, status text not null, blocker text, updated_at timestamptz not null default now());
create table public.dd_code_repair_work_queue (id uuid not null default gen_random_uuid() primary key, policy_key text not null, work_key text not null unique, failure_kind text not null, failure_evidence jsonb not null default '{}', repo text not null default 'DaniDeclares/admiring-star-8zkzvl', target_branch text not null default 'main', status text not null default 'QUEUED', execution_mode text not null default 'DRY_RUN', last_result jsonb not null default '{}', attempts integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), governed_run_id uuid, decision_snapshot_id uuid, external_action_id uuid, claimed_by text, claimed_at timestamptz);
create table public.dd_promotion_candidates (id uuid not null default gen_random_uuid() primary key, candidate_key text not null unique, component_domain text not null, component_name text not null, source_environment text not null default 'TESTER', target_environment text not null default 'PRODUCTION', source_reference text, classification text not null default 'PROMOTE_AFTER_FIX', proof_status text not null default 'UNPROVEN', dependency_status text not null default 'UNCHECKED', security_status text not null default 'UNCHECKED', production_diff_status text not null default 'UNCHECKED', rollback_status text not null default 'UNDEFINED', owner_approval_status text not null default 'NOT_REQUESTED', production_verification_status text not null default 'NOT_RUN', blocking_reason text, evidence jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
insert into public.dd_code_repair_policy(policy_key,detection_authority,branch_policy,status) values ('PLATFORM_SAFE_MANIFEST_V2','x','x','ACTIVE');
-- Production's current claim function, captured read-only 2026-10-11 (rollback baseline)
create or replace function public.dd_claim_autobuild_candidate(p_worker_key text) returns setof dd_autobuild_candidates language plpgsql set search_path to 'public' as $function$
begin
  if nullif(btrim(p_worker_key),'') is null then raise exception 'worker key required'; end if;
  return query with candidate as (select id from public.dd_autobuild_candidates where status in ('MANIFEST_READY','READY','QUEUED_FOR_BUILD') and risk_tier='LOW' and permission_class in ('CODE_BUILD','AUTO_PR_BUILD') and executor_state='PENDING' and blocker is null and (case when proposed_build is null then false else (proposed_build::jsonb->>'kind')='PATCH_MANIFEST_V1' and jsonb_typeof(proposed_build::jsonb->'files')='array' and jsonb_array_length(proposed_build::jsonb->'files')>0 end) order by created_at,id for update skip locked limit 1)
  update public.dd_autobuild_candidates c set executor_state='LEASED',lease_owner=p_worker_key,leased_at=now(),lease_expires_at=now()+interval '20 minutes' from candidate where c.id=candidate.id returning c.*;
end $function$;
